ction-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6ODgzLCJ1cmwiOiJodHRwczpcL1wvbHBhZXpzaXMuY2xcL3dwLWNvbnRlbnRcL3VwbG9hZHNcLzIwMjJcLzA0XC9DYXB0dXJhLWRlLVBhbnRhbGxhLTIwMjItMDQtMTktYS1sYXMtMTUuNDcuMDIucG5nIiwic2xpZGVzaG93IjoiMGZkMzAxYSJ9\">\n					<div class=\"e-gallery-image elementor-gallery-item__image\" data-thumbnail=\"https://lpaezsis.cl/wp-content/uploads/2022/04/Captura-de-Pantalla-2022-04-19-a-las-15.47.02.png\" data-width=\"114\" data-height=\"114\" aria-label=\"\" role=\"img\" ></div>\n											<div class=\"elementor-gallery-item__overlay\"></div>\n														</a>\n					</div>\n					</div>\n				</div>\n					</div>\n		</div>\n					</div>\n		</section>\n				<section class=\"elementor-section elementor-top-section elementor-element elementor-element-66255d3 elementor-section-full_width elementor-section-stretched elementor-section-height-default elementor-section-height-default\" data-id=\"66255d3\" data-element_type=\"section\" data-e-type=\"section\" data-settings=\"{&quot;stretch_section&quot;:&quot;section-stretched&quot;}\">\n						<div class=\"elementor-container elementor-column-gap-default\">\n					<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-20dc1cd\" data-id=\"20dc1cd\" data-element_type=\"column\" data-e-type=\"column\">\n			<div class=\"elementor-widget-wrap elementor-element-populated\">\n						<div class=\"elementor-element elementor-element-8e68dc8 elementor-widget elementor-widget-heading\" data-id=\"8e68dc8\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"heading.default\">\n				<div class=\"elementor-widget-container\">\n					<h2 class=\"elementor-heading-title elementor-size-default\">Tester de Control de Embalaje:</h2>				</div>\n				</div>\n				<div class=\"elementor-element elementor-element-916b58d elementor-widget elementor-widget-text-editor\" data-id=\"916b58d\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"text-editor.default\">\n				<div class=\"elementor-widget-container\">\n									<p>Lo único que protege su producto de daños estructurales o ambientales<br />es el embalaje en el que se envía. Ya sea que se envíe en una caja de<br />cartón, una caja o una caja de diseño personalizado, ya sea a nivel<br />nacional o internacional, debe asegurarse de que el embalaje cumpla con<br />los requisitos para evitar daños durante el tránsito.</p>								</div>\n				</div>\n				<div class=\"elementor-element elementor-element-3de42a0 elementor-icon-list--layout-traditional elementor-list-item-link-full_width elementor-invisible elementor-widget elementor-widget-icon-list\" data-id=\"3de42a0\" data-element_type=\"widget\" data-e-type=\"widget\" data-settings=\"{&quot;_animation&quot;:&quot;fadeIn&quot;}\" data-widget_type=\"icon-list.default\">\n				<div class=\"elementor-widget-container\">\n							<ul class=\"elementor-icon-list-items\">\n							<li class=\"elementor-icon-list-item\">\n											<span class=\"elementor-icon-list-icon\">\n							<i aria-hidden=\"true\" class=\"fas fa-check\"></i>						</span>\n										<span class=\"elementor-icon-list-text\">Proteja el producto</span>\n									</li>\n								<li class=\"elementor-icon-list-item\">\n											<span class=\"elementor-icon-list-icon\">\n							<i aria-hidden=\"true\" class=\"fas fa-check\"></i>						</span>\n										<span class=\"elementor-icon-list-text\">Ahorre dinero. Cada vez que su producto se daña durante el envío, pierde dinero.</span>\n									</li>\n								<li class=\"elementor-icon-list-item\">\n											<span class=\"elementor-icon-list-icon\">\n							<i aria-hidden=\"true\" class=\"fas fa-check\"></i>						</span>\n										<span class=\"elementor-icon-list-text\">Incrementar la lealtad a la marca.</span>\n									</li>\n								<li class=\"elementor-icon-list-item\">\n											<span class=\"elementor-icon-list-icon\">\n							<i aria-hidden=\"true\" class=\"fas fa-check\"></i>						</span>\n										<span class=\"elementor-icon-list-text\">Reduzca la necesidad de envíos de prueba.</span>\n									</li>\n								<li class=\"elementor-icon-list-item\">\n											<span class=\"elementor-icon-list-icon\">\n							<i aria-hidden=\"true\" class=\"fas fa-check\"></i>						</span>\n										<span class=\"elementor-icon-list-text\">Reduce los dolores de cabeza por reclamos de productos.</span>\n									</li>\n						</ul>\n						</div>\n				</div>\n					</div>\n		</div>\n				<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-131b8be\" data-id=\"131b8be\" data-element_type=\"column\" data-e-type=\"column\">\n			<div class=\"elementor-widget-wrap elementor-element-populated\">\n						<section class=\"elementor-section elementor-inner-section elementor-element elementor-element-53ca66d elementor-section-full_width elementor-section-height-default elementor-section-height-default\" data-id=\"53ca66d\" data-element_type=\"section\" data-e-type=\"section\">\n						<div class=\"elementor-container elementor-column-gap-no\">\n					<div class=\"elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-4c6089f\" data-id=\"4c6089f\" data-element_type=\"column\" data-e-type=\"column\">\n			<div class=\"elementor-widget-wrap elementor-element-populated\">\n						<div class=\"elementor-element elementor-element-b99a453 elementor-widget elementor-widget-image\" data-id=\"b99a453\" data-element_type=\"widget\" data-e-type=\"widget\" data-widget_type=\"image.default\">\n				<div class=\"elementor-widget-container\">\n																														</div>\n				</div>\n					</div>\n		</div>\n					</div>\n		</section>\n					</div>\n		</div>\n					</div>\n		</section>\n				</div>','[\"https://lpaezsis.cl/wp-content/uploads/2022/04/Captura-de-Pantalla-2022-04-19-a-las-15.44.11.png\",\"https://lpaezsis.cl/wp-content/uploads/2022/04/Captura-de-Pantalla-2022-04-19-a-las-15.46.06.png\",\"https://lpaezsis.cl/wp-content/uploads/2022/04/Captura-de-Pantalla-2022-04-19-a-las-15.49.47.png\"]',60,1,'2026-07-18 23:51:59'),
